#!/usr/bin/env node
import{access,constants,readdir,rm,writeFile}from"node:fs/promises";import{exec}from"node:child_process";import{exit}from"node:process";import{promisify}from"node:util";class AkriUnit{successes=0;failiures=[];path;filter;startTime;constructor(t=null){this.startTime=Date.now(),this.filter=t}async fail(t){console.error(t instanceof Error?t:new Error(t)),exit(1)}async executeTests(t){await this.setPath(t),await this.runFiles(),await this.testReport()}async setPath(t){try{if(!t||"string"!=typeof t)throw new TypeError("Argument #1 (path) must not be empty");await access(t,constants.R_OK)}catch(t){this.fail(t)}this.path=t}async testReport(){0==this.failiures.length?(console.log("OK"),await this.deleteFailReportFile()):this.outputFailReport(),console.log(`AkriUnit executed with ${this.successes} passed, ${this.failiures.length} failiures.`),console.log(`Finished in ${(Date.now()-this.startTime)/1e3}s`)}outputFailReport(){let t="AkriUnit test failiure report:\n\n";for(const e of this.failiures)console.error("--"+e),t+=e+"\n\n";console.error("Failiures!"),this.generateFailReportFile(t),console.error(`Generated fail report at ${this.path}/aureport.txt`)}async deleteFailReportFile(){await rm(this.path+"/aureport.txt",{force:!0})}async generateFailReportFile(t=""){await writeFile(`${this.path}/aureport.txt`,t)}updateTotalStats(t,e,s){if(e)throw new Error(e);try{let e=this.decodeFileOutput(t);this.failiures=this.failiures.concat(e.failiures),this.successes+=e.successes}catch(t){console.fail(t??`Output of test file ${s} could not be parsed. Please make sure you instantiate your test class at the end of the file.`)}}decodeFileOutput(t){const e=JSON.parse(t);if("number"!=typeof e?.successes||"object"!=typeof e?.failiures)throw new Error("File passed valid JSON data, but not in the correct format. Please ensure your test class extends AkriUnit's TestCase class.");return e}async runFiles(){const t=await readdir(this.path);for(const e of t){if(!e.match(".js"))continue;const t=e.substr(e.length-3,3);if("string"==typeof this.filter&&""!==this.filter&&!e.match(this.filter)&&!t.match(this.filter))continue;const s=promisify(exec),{stdout:i,stderr:r}=await s(`node ${this.path}/${e}`);this.updateTotalStats(i,r,e)}}}const testrunner=new AkriUnit(process.argv[3]??null);testrunner.executeTests(process.argv[2]??null);